import{d as g,C as e,o as u,c as h,a3 as i,E as t,j as a,a as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·乡党","description":"《论语》第 10 篇「乡党」——二十七章原文与导读。孔子在乡党、朝廷、出使、斋戒、饮食、燕居中的一举一动，全书体例最特殊的一篇。","frontmatter":{"title":"论语·乡党","description":"《论语》第 10 篇「乡党」——二十七章原文与导读。孔子在乡党、朝廷、出使、斋戒、饮食、燕居中的一举一动，全书体例最特殊的一篇。","category":"guide","aliases":["乡党","乡党篇","乡党第十","论语乡党","lunyu 乡党"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-10.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-10.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/lunyu/chapter-10.md"},x=g({...d,setup(y){const s=[{id:"yi",label:"一、孔子于乡党",showLabel:!0,sentences:[["孔子于乡党，",{text:"恂恂如",glossary:"xunxunru"},"也，似不能言者；其在宗庙朝庭，",{text:"便便言",glossary:"bianbianyan"},"，唯谨尔。"]],note:"孔子在乡党（本乡本土）恭顺谨慎（恂恂如也），像是不会说话的样子；在宗庙朝廷上，则明白流畅地说话（便便言），只是仍存谨慎。此章写孔子随境而异的气象。"},{id:"er",label:"二、朝，与下大夫言",showLabel:!0,sentences:[["朝，与下大夫言，",{text:"侃侃如",glossary:"kankanru"},"也；与上大夫言，",{text:"訚訚如",glossary:"yinyinru"},"也。君在，",{text:"踧踖如",glossary:"cujiru"},"也，与与如也。"]],note:"上朝时，与下大夫说话刚直从容（侃侃如也），与上大夫说话和悦而正直（訚訚如也）。国君在时，恭敬而局促不安（踧踖如也），又威仪适度（与与如也）。"},{id:"san",label:"三、君召使摈",showLabel:!0,sentences:[["君召使",{text:"摈",glossary:"bin"},"，色",{text:"勃如",glossary:"boru"},"也，足",{text:"躩如",glossary:"jueru"},"也。揖所与立，左右手，衣前后，",{text:"襜如",glossary:"chanru"},"也。趋进，翼如也。宾退，必复命曰：“宾不顾矣。”"]],note:"「君召使摈」——国君召他去导引外宾，孔子脸色庄重（勃如），脚步迅捷（躩如）。向同立者作揖，左右拱手，衣裳前后摆动而整齐（襜如）。快步向前时如鸟展翅（翼如）。宾客退去后，必回报：「宾不顾矣」（客人不再回头了）。"},{id:"si",label:"四、入公门，鞠躬如也",showLabel:!0,sentences:[["入公门，鞠躬如也，如不容。立不中门，行不履阈。过位，色勃如也，足躩如也，其言似不足者。摄齐升堂，鞠躬如也，屏气似不息者。出，降一等，逞颜色，怡怡如也；没阶，趋进，翼如也；复其位，踧踖如也。"]],note:"「入公门，鞠躬如也，如不容」——入国君宫门，低头躬身，像无处容身。「立不中门，行不履阈」——不立于门中，行不踩门槛。「过位，色勃如也，足躩如也，其言似不足者」——经过国君之位，面色庄重，脚步迅捷，说话像中气不足。「摄齐升堂，鞠躬如也，屏气似不息者」——提起衣摆上堂，躬身屏息如不呼吸。「出，降一等，逞颜色，怡怡如也；没阶，趋进，翼如也；复其位，踧踖如也」——出而下一级台阶，脸色放松、和悦；走完台阶，快步如鸟展翅；回到己位，又恭敬不安。"},{id:"wu",label:"五、执圭，鞠躬如也",showLabel:!0,sentences:[["执圭，鞠躬如也，如不胜。上如揖，下如授。",{text:"勃如战色",glossary:"boruzhanse"},"，足",{text:"蹜蹜",glossary:"susu"},"如有循。享礼，有容色。私觌，愉愉如也。"]],note:"「执圭，鞠躬如也，如不胜」——出使时手执玉圭，躬身像拿不动（圭为君命之信物）。「上如揖，下如授」——举起如作揖，放下如授物。「勃如战色，足蹜蹜如有循」——面色庄重如临战，脚步细碎像沿物而行。「享礼，有容色」——献礼时面容和悦。「私觌，愉愉如也」——私下相见时，愉快从容。"},{id:"liu",label:"六、君子不以绀緅饰",showLabel:!0,sentences:[["君子不以",{text:"绀緅",glossary:"ganzou"},"饰，红紫不以为",{text:"亵服",glossary:"xiefu"},"。当暑",{text:"袗絺绤",glossary:"zhenchixi"},"，必表而出之。缁衣",{text:"羔裘",glossary:"gaoqiu"},"，素衣",{text:"麑裘",glossary:"niqiu"},"，黄衣狐裘。亵裘长，短右",{text:"袂",glossary:"mei"},"。必有寝衣，长一身有半。狐貉之厚以居。去丧，无所不佩。非",{text:"帷裳",glossary:"weishang"},"，必杀之。羔裘玄冠不以吊。",{text:"吉月",glossary:"jiyue"},"，必朝服而朝。"]],note:"此章详记孔子衣服之制：不用青红（绀緅）之色作镶边，不用红紫作居家之服；暑天穿粗葛细葛之单衣，必加外衣而出；黑衣配羔裘、素衣配麑裘、黄衣配狐裘；居家之裘较长而右袖较短；必有寝衣（被），长一身有半；狐貉厚毛用作家居之裘；服丧既除则无不可佩之饰；非帷裳（朝祭之服）者必裁杀之；羔裘玄冠不用于吊丧；吉月（每月朔日）必穿朝服而朝。"},{id:"qi",label:"七、齐，必有明衣",showLabel:!0,sentences:[["齐，必有明衣，布。齐必变食，居必迁坐。"]],note:"「齐（斋），必有明衣，布」——斋戒时必有浴衣，以布为之。「齐必变食，居必迁坐」——斋戒必改变饮食，居处必换其所（不与妻室同处）。"},{id:"ba",label:"八、食不厌精，脍不厌细",showLabel:!0,sentences:[["食不厌精，",{text:"脍",glossary:"kuai"},"不厌细。食",{text:"饐而餲",glossary:"yiai"},"，鱼馁而肉败，不食；色恶，不食；臭恶，不食；失饪，不食；不时，不食；割不正，不食；不得其酱，不食。肉虽多，不使胜食气。唯酒无量，不及乱。沽酒市脯，不食。不撤姜食，不多食。"]],note:"此章详记孔子饮食之节：饭食不厌精细，鱼脍不厌切细。「食饐而餲、鱼馁而肉败，不食；色恶，不食；臭恶，不食；失饪，不食；不时，不食；割不正，不食；不得其酱，不食」——饭变味、（鱼）肉腐坏、色恶、味恶、烹调失当、非其时、切割不正、无其酱，皆不食。「肉虽多，不使胜食气」——肉虽多，不使超过饭量。「唯酒无量，不及乱」——唯酒不限量，但不至昏乱。「沽酒市脯，不食」——买来之酒与市上干肉，不食。「不撤姜食，不多食」——姜不撤去，但不多吃。"},{id:"jiu",label:"九、祭于公，不宿肉",showLabel:!0,sentences:[["祭于公，不宿肉。祭肉不出三日，出三日不食之矣。"]],note:"「祭于公，不宿肉」——参与国君之祭，所得之肉不留过夜。「祭肉不出三日，出三日不食之矣」——家祭之肉不出三日，过三日便不食了。"},{id:"shi",label:"十、食不语，寝不言",showLabel:!0,sentences:[["食不语，寝不言。"]],note:"「食不语，寝不言」——吃饭时不交谈，睡觉时不言语。"},{id:"shiyi",label:"十一、虽疏食菜羹，瓜祭",showLabel:!0,sentences:[["虽疏食菜羹，瓜祭，必齐如也。"]],note:"「虽疏食菜羹，瓜祭，必齐如也」——纵然是粗饭菜汤，也必先祭（古人食前祭先），且必肃敬如斋（齐如＝肃敬之貌）。"},{id:"shier",label:"十二、席不正，不坐",showLabel:!0,sentences:[["席不正，不坐。"]],note:"「席不正，不坐」——坐席摆放不端正，便不坐。"},{id:"shisan",label:"十三、乡人饮酒，杖者出",showLabel:!0,sentences:[["乡人饮酒，杖者出，斯出矣。"]],note:"「乡人饮酒，杖者出，斯出矣」——与乡人饮酒（行乡饮酒礼），待拄杖之老人（年长者）离席后，自己才出。"},{id:"shisi",label:"十四、乡人傩",showLabel:!0,sentences:[["乡人",{text:"傩",glossary:"nuo"},"，朝服而立于",{text:"阼阶",glossary:"zuojie"},"。"]],note:"「乡人傩，朝服而立于阼阶」——乡人举行驱疫之傩礼时，孔子穿着朝服立于东阶之上（既敬乡人之礼，又守己之位）。"},{id:"shiwu",label:"十五、问人于他邦，再拜而送之",showLabel:!0,sentences:[["问人于他邦，再拜而送之。"]],note:"「问人于他邦，再拜而送之」——派人到他国问候朋友，孔子必拜两次以送使者（如拜受其问候之人）。"},{id:"shiliu",label:"十六、丘未达，不敢尝",showLabel:!0,sentences:[["康子馈药，拜而受之。曰：“丘未达，不敢尝。”"]],note:"「康子馈药，拜而受之。曰：丘未达，不敢尝」——季康子送药，孔子拜受而说：我对这药性未通晓，不敢尝。受而不尝，见其诚正。"},{id:"shiqi",label:"十七、伤人乎？不问马",showLabel:!0,sentences:[["厩焚，子退朝，曰：“伤人乎？”不问马。"]],note:"「厩焚，子退朝，曰：伤人乎？不问马」——马房失火，孔子退朝回来，问：伤到人了吗？并不问马。见其重人轻物。"},{id:"shiba",label:"十八、君赐食，必正席先尝之",showLabel:!0,sentences:[["君赐食，必正席先尝之；君赐腥，必熟而荐之；君赐生，必畜之。侍食于君，君祭，先饭。"]],note:"「君赐食，必正席先尝之」——国君赐熟食，必摆正坐席先尝之；「君赐腥，必熟而荐之」——赐生肉，必煮熟而后献祭；「君赐生，必畜之」——赐活物，必养起来。「侍食于君，君祭，先饭」——陪国君进食，国君行祭食之礼时，自己先为君尝饭。"},{id:"shijiu",label:"十九、疾，君视之，东首",showLabel:!0,sentences:[["疾，君视之，",{text:"东首",glossary:"dongshou"},"，加朝服，",{text:"拖绅",glossary:"tuoshen"},"。"]],note:"「疾，君视之，东首，加朝服，拖绅」——有病，国君来看望，便头朝东（东为首，示受君命），并把朝服盖在身上，拖着束带（绅）。"},{id:"ershi",label:"二十、君命召，不俟驾行矣",showLabel:!0,sentences:[["君命召，不",{text:"俟驾",glossary:"sijia"},"行矣。"]],note:"「君命召，不俟驾行矣」——国君命召，不等车马备好便先行。"},{id:"ershiyi",label:"二十一、入太庙，每事问",showLabel:!0,sentences:[["入太庙，每事问。"]],note:"「入太庙，每事问」——进入太庙，每事皆问。（与《八佾》第十五章重出。）"},{id:"ershier",label:"二十二、朋友死，无所归",showLabel:!0,sentences:[["朋友死，无所归，曰：“于我",{text:"殡",glossary:"bin-zang"},"。”"]],note:"「朋友死，无所归，曰：于我殡」——朋友死了，无处归葬，孔子说：由我来料理其丧事（殡＝停柩治丧）。"},{id:"ershisan",label:"二十三、朋友之馈，虽车马",showLabel:!0,sentences:[["朋友之馈，虽车马，非祭肉，不拜。"]],note:"「朋友之馈，虽车马，非祭肉，不拜」——朋友所赠，纵是车马之贵重，若非祭肉，则不拜受（祭肉为祭先祖之胙，故当拜）。"},{id:"ershisi",label:"二十四、寝不尸，居不容",showLabel:!0,sentences:[["寝不尸，居不容。（居不容 一作：居不客）"]],note:"「寝不尸，居不容」——睡卧时不像死尸那样僵直仰卧（尸＝仰卧如尸）；居家时不像作客那样拘谨（容，一作「客」）。"},{id:"ershiwu",label:"二十五、见齐衰者，虽狎，必变",showLabel:!0,sentences:[["见齐衰者，虽狎，必变。见冕者与瞽者，虽",{text:"亵",glossary:"xie-qin"},"，必以貌。凶服者",{text:"式",glossary:"shi-che"},"之，式负版者。有盛馔，必变色而作。迅雷风烈，必变。"]],note:"「见齐衰者，虽狎，必变」——见穿丧服者，虽平日亲昵，也必变色（示哀）；「见冕者与瞽者，虽亵，必以貌」——见戴礼冠者与盲人，虽常见，也必以礼貌待之。「凶服者式之，式负版者」——乘车遇穿丧服者则俯身扶轼（式＝车前横木，俯身示敬），遇背负图籍者亦然。「有盛馔，必变色而作」——主人设盛馔，必变色而起。「迅雷风烈，必变」——遇迅雷烈风，必变色（示敬畏天变）。"},{id:"ershiliu",label:"二十六、升车，必正立，执绥",showLabel:!0,sentences:[["升车，必正立，执绥。车中不内顾，不疾言，不亲指。"]],note:"「升车，必正立，执绥」——上车，必端正而立，手挽绥（上车所挽之索）。「车中不内顾，不疾言，不亲指」——在车中不回头内顾，不急促言语，不亲手指画。"},{id:"ershiqi",label:"二十七、色斯举矣",showLabel:!0,sentences:[["色斯举矣，翔而后集。曰：“山梁雌雉，时哉时哉！”子路共之，三嗅而作。"]],note:"「色斯举矣，翔而后集」——（鸟见人）颜色一动便飞起，盘旋一阵而后落下。「曰：山梁雌雉，时哉时哉」——（孔子）说：山梁上的雌雉，懂得时宜啊，懂得时宜啊！子路向它拱了拱手（共＝拱），它振动翅膀（嗅，一说当作「狊」，鸟张两翅）飞走了。此章境界悠远，历来解说纷歧。"}],r=[{id:"xunxunru",term:"恂恂如",pinyin:"xún xún rú",meaning:"恭顺谨慎的样子。在乡党面对父老，孔子不逞才，像不大会说话的人。"},{id:"bianbianyan",term:"便便言",pinyin:"pián pián yán",meaning:"说话明白流畅、有条理。宗庙朝廷是公事场合，故说得清楚而仍谨慎。"},{id:"kankanru",term:"侃侃如",pinyin:"kǎn kǎn rú",meaning:"刚直而和乐的样子。"},{id:"yinyinru",term:"訚訚如",pinyin:"yín yín rú",meaning:"和悦而正直的样子。"},{id:"cujiru",term:"踧踖如",pinyin:"cù jí rú",meaning:"恭敬而不安的样子。君在座，敬而自省。"},{id:"bin",term:"摈",pinyin:"bìn",meaning:"同「傧」，引导宾客、担任司仪。"},{id:"boru",term:"勃如",pinyin:"bó rú",meaning:"神色庄重、变色肃然的样子。"},{id:"jueru",term:"躩如",pinyin:"jué rú",meaning:"脚步疾速的样子。"},{id:"chanru",term:"襜如",pinyin:"chān rú",meaning:"衣服摆动整齐的样子。"},{id:"boruzhanse",term:"勃如战色",pinyin:"bó rú zhàn sè",meaning:"神色庄重，如临战阵。执圭出使，所担者重，故其色如此。"},{id:"susu",term:"蹜蹜",pinyin:"sù sù",meaning:"脚步细密、谨慎而行的样子。"},{id:"ganzou",term:"绀緅",pinyin:"gàn zōu",meaning:"绀、緅都是深青透红的颜色，近于斋服与丧服之色，故不用作镶边。"},{id:"xiefu",term:"亵服",pinyin:"xiè fú",meaning:"日常在家穿的便服。红紫非正色，不作便服。"},{id:"zhenchixi",term:"袗絺绤",pinyin:"zhěn chī xì",meaning:"袗：单衣；絺绤：粗细葛布。夏天穿葛布单衣，出外必加外衣。"},{id:"kuai",term:"脍",pinyin:"kuài",meaning:"切细的肉（鱼、肉片）。"},{id:"yiai",term:"饐而餲",pinyin:"yì ér ài",meaning:"食物经久变味发臭。饐：久放发臭；餲：变味。"},{id:"nuo",term:"傩",pinyin:"nuó",meaning:"古代驱除疫鬼的仪式。乡人举行时，孔子穿朝服立于东阶（主人之位）——重在参与而不废礼。"},{id:"zuojie",term:"阼阶",pinyin:"zuò jiē",meaning:"堂前东面的台阶，主人所立之位。"},{id:"bin-zang",term:"殡",pinyin:"bìn",meaning:"停放灵柩、料理丧事。于我殡：由我来办理丧事。"},{id:"xie-qin",term:"亵",pinyin:"xiè",meaning:"亲近而随便。虽亵，必以貌：即使很熟，也一定以礼相待。"},{id:"shi-che",term:"式",pinyin:"shì",meaning:"同「轼」，手扶车前横木俯身，表示敬意。"},{id:"gaoqiu",term:"羔裘",pinyin:"gāo qiú",meaning:"羔：黑色羊皮（一说小羊）。羔裘配缁衣（黑衣）。"},{id:"niqiu",term:"麑裘",pinyin:"ní qiú",meaning:"麑：小鹿。麑裘配素衣（白衣）。"},{id:"mei",term:"袂",pinyin:"mèi",meaning:"袖子。短右袂：右袖做短些，便于做事。"},{id:"weishang",term:"帷裳",pinyin:"wéi shang",meaning:"朝祭之服，用整幅布制成、不加剪裁。非帷裳，必杀之：不是帷裳的，一定裁去多余的布。"},{id:"jiyue",term:"吉月",pinyin:"jí yuè",meaning:"正月（一说每月朔日）。吉月必朝服而朝：正月初一定穿朝服上朝。"},{id:"dongshou",term:"东首",pinyin:"dōng shǒu",meaning:"头朝东。古人卧以北为尊、以东为生方；君来视疾，故改卧向，头朝东以示敬君。"},{id:"tuoshen",term:"拖绅",pinyin:"tuō shēn",meaning:"绅：束在腰间、垂下的大带。卧病不能起身更衣，便加朝服于身、拖下腰带，如朝见之状。"},{id:"sijia",term:"俟驾",pinyin:"sì jià",meaning:"等候车马驾好。不俟驾行矣：不等车马备好就步行前往——闻召即动，急君命。"}];return(p,n)=>{const o=e("DaoTextReading"),l=e("DaoKeywordCards");return u(),h("div",null,[n[0]||(n[0]=i("",7)),t(o,{colophon:"乡党第十 · 二十七章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·乡党 原文"}),n[1]||(n[1]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[m("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(l,{items:[{term:"恂恂如",pinyin:["xún","xún","rú"],meaning:"恭顺谨慎的样子。在乡党面对父老，孔子不逞才，像不大会说话的人。"},{term:"便便言",pinyin:["pián","pián","yán"],meaning:"说话明白流畅、有条理。宗庙朝廷是公事场合，故说得清楚而仍谨慎。"},{term:"侃侃如",pinyin:["kǎn","kǎn","rú"],meaning:"刚直而和乐的样子。"},{term:"訚訚如",pinyin:["yín","yín","rú"],meaning:"和悦而正直的样子。"},{term:"踧踖如",pinyin:["cù","jí","rú"],meaning:"恭敬而不安的样子。君在座，敬而自省。"},{term:"摈",pinyin:["bìn"],meaning:"同「傧」，引导宾客、担任司仪。"},{term:"勃如",pinyin:["bó","rú"],meaning:"神色庄重、变色肃然的样子。"},{term:"躩如",pinyin:["jué","rú"],meaning:"脚步疾速的样子。"},{term:"襜如",pinyin:["chān","rú"],meaning:"衣服摆动整齐的样子。"},{term:"勃如战色",pinyin:["bó","rú","zhàn","sè"],meaning:"神色庄重，如临战阵。执圭出使，所担者重，故其色如此。"},{term:"蹜蹜",pinyin:["sù","sù"],meaning:"脚步细密、谨慎而行的样子。"},{term:"绀緅",pinyin:["gàn","zōu"],meaning:"绀、緅都是深青透红的颜色，近于斋服与丧服之色，故不用作镶边。"},{term:"亵服",pinyin:["xiè","fú"],meaning:"日常在家穿的便服。红紫非正色，不作便服。"},{term:"袗絺绤",pinyin:["zhěn","chī","xì"],meaning:"袗：单衣；絺绤：粗细葛布。夏天穿葛布单衣，出外必加外衣。"},{term:"脍",pinyin:["kuài"],meaning:"切细的肉（鱼、肉片）。"},{term:"饐而餲",pinyin:["yì","ér","ài"],meaning:"食物经久变味发臭。饐：久放发臭；餲：变味。"},{term:"傩",pinyin:["nuó"],meaning:"古代驱除疫鬼的仪式。乡人举行时，孔子穿朝服立于东阶（主人之位）——重在参与而不废礼。"},{term:"阼阶",pinyin:["zuò","jiē"],meaning:"堂前东面的台阶，主人所立之位。"},{term:"殡",pinyin:["bìn"],meaning:"停放灵柩、料理丧事。于我殡：由我来办理丧事。"},{term:"亵",pinyin:["xiè"],meaning:"亲近而随便。虽亵，必以貌：即使很熟，也一定以礼相待。"},{term:"式",pinyin:["shì"],meaning:"同「轼」，手扶车前横木俯身，表示敬意。"},{term:"羔裘",pinyin:["gāo","qiú"],meaning:"羔：黑色羊皮（一说小羊）。羔裘配缁衣（黑衣）。"},{term:"麑裘",pinyin:["ní","qiú"],meaning:"麑：小鹿。麑裘配素衣（白衣）。"},{term:"袂",pinyin:["mèi"],meaning:"袖子。短右袂：右袖做短些，便于做事。"},{term:"帷裳",pinyin:["wéi","shang"],meaning:"朝祭之服，用整幅布制成、不加剪裁。非帷裳，必杀之：不是帷裳的，一定裁去多余的布。"},{term:"吉月",pinyin:["jí","yuè"],meaning:"正月（一说每月朔日）。吉月必朝服而朝：正月初一定穿朝服上朝。"},{term:"东首",pinyin:["dōng","shǒu"],meaning:"头朝东。古人卧以北为尊、以东为生方；君来视疾，故改卧向，头朝东以示敬君。"},{term:"拖绅",pinyin:["tuō","shēn"],meaning:"绅：束在腰间、垂下的大带。卧病不能起身更衣，便加朝服于身、拖下腰带，如朝见之状。"},{term:"俟驾",pinyin:["sì","jià"],meaning:"等候车马驾好。不俟驾行矣：不等车马备好就步行前往——闻召即动，急君命。"}]}),n[2]||(n[2]=i("",21))])}}});export{c as __pageData,x as default};
